// Formata o output para Slack com Markdown enriquecido
const rawOutput = $input.item.json.output;

// Aplica formatação Slack (mrkdwn)
const formattedOutput = rawOutput
  // Títulos principais
  .replace(/^## (.*?)$/gm, '*$1*\n━━━━━━━━━━━━━━━━')
  // Subtítulos
  .replace(/^### (.*?)$/gm, '▸ *$1*')
  // Negrito para labels
  .replace(/\*\*(.*?)\*\*/g, '*$1*')
  // Código inline
  .replace(/`(.*?)`/g, '`$1`')
  // Listas com melhor espaçamento
  .replace(/^\* /gm, '  • ')
  .replace(/^- /gm, '  • ');

// Adiciona cabeçalho visual
const finalOutput = `
📋 *DOCUMENTAÇÃO DE REQUISITOS GERADA*
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

${formattedOutput}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
_Gerado automaticamente via DocIA • ${new Date().toLocaleString('pt-BR')}_
`;

return { json: { formattedOutput: finalOutput } };
